import json,pathlib,collections,datetime
p=pathlib.Path(__file__).parent;d=json.loads((p/'manifest.json').read_text());arts=d['artifacts'];src=d['sources'];good=[s for s in src if s['artifactCount']];sha=collections.Counter(a['sha256'] for a in arts)
lines=['# Community GitHub Langflow graph corpus','',f'Collected at {datetime.datetime.now(datetime.timezone.utc).isoformat()}.', '',f'- Repositories inventoried: {len(src)}',f'- Repositories with graph JSON: {len(good)}',f'- Raw graph-bearing JSON artifacts: {len(arts)}',f'- Distinct SHA256 byte contents: {len(sha)}',f'- Exact duplicate artifact instances: {len(arts)-len(sha)}',f'- Downloaded artifact bytes: {sum(a["bytes"] for a in arts)}',f'- Failures recorded: {len(d["failures"])}','','## Discovery','', 'Primary GitHub repository search API queries, sorted by stars, first 100 results per query (search response snapshots retained):','']
for q in d['queries']:lines.append('- `'+q+'`')
lines += ['', 'The search-result ceiling is a discovery limit, not exhaustive coverage of all public GitHub repositories. GitHub default repository search excludes forks unless explicitly requested. Sources outside langflow-ai were selected from these results; mirrored/copied source families can still exist and are not presumed independent.', '', '## Collection and exclusions','', 'Each repository is pinned to its default-branch commit at collection. Recursive Git trees inventory JSON paths. All JSON candidates between 21 bytes and 8 MB are inspected, excluding node_modules and Python environment paths and package lockfiles. A graph-bearing JSON requires a nodes array, edges array, and at least one node with data or type; nested graph objects and arrays are inspected. Raw bytes are saved without normalization. This broad structural gate still requires Langflow-specific downstream validation.', '', 'License text is collected from LICENSE, COPYING and NOTICE basenames (up to 200 KB each; up to ten files per repository). Reported SPDX values originate from GitHub metadata. Presence of license text does not establish its scope over every flow. Missing licenses remain unknown. No downloaded code was executed and no repository dependencies were installed.', '', 'Initial JSON scanning guard: first 500 eligible paths per repository. Remaining limits are listed below; successful source counts do not prove independence or permission. Non-JSON embedded examples, archives, branches other than default, Git LFS payloads, and inaccessible submodules are not collected.', '', '## Coverage limits','']
limits=[s for s in src if s.get('treeTruncated') or s.get('jsonCandidates',0)>s.get('jsonCandidatesExamined',0)]
if not limits:lines.append('No collected repository hit the recursive-tree truncation or 500 eligible JSON guard.')
for s in limits:lines.append(f'- {s["repository"]}: JSON {s.get("jsonCandidatesExamined")}/{s.get("jsonCandidates")}; treeTruncated={s.get("treeTruncated")}')
lines += ['', '## Sources with graph artifacts','', '| Repository | Pinned commit | Artifacts | License metadata |','|---|---|---:|---|']
for s in sorted(good,key=lambda x:(-x['artifactCount'],x['repository'])):
 repo=s['repository'];rev=s['revision'];lic=s.get('license',{})
 lines.append(f'| [{repo}](https://github.com/{repo}/tree/{rev}) | `{rev}` | {s["artifactCount"]} | {lic.get("spdx") or "unknown"}; {lic.get("status","unknown")} |')
lines += ['', 'The manifest preserves each original path, pinned raw source URL, repository, revision, SHA256, collection timestamp, byte length, license record, and fork flag. Failed candidates and download failures are retained in `failures`. Repositories with zero accepted graphs remain in `sources` as exclusions rather than being silently omitted.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n')
print(len(src),len(good),len(arts),len(sha),len(limits))
